<div class="page-header"><div><h2><?= e($product['name']) ?></h2><p><?= e($product['description']) ?></p></div><a class="btn btn-secondary" href="<?= e(url('/produtos')) ?>">Voltar</a></div>
<section class="panel"><div class="panel-header"><h3>Produções relacionadas</h3><p>Um produto pode ser produzido por várias crianças; o vínculo ocorre pela produção.</p></div><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Aluno</th><th>Trabalho</th><th>Oficina</th><th>Quantidade</th><th>Situação</th></tr></thead><tbody><?php foreach($productions as $p): ?><tr><td><?= e(date('d/m/Y',strtotime($p['produced_at']))) ?></td><td><?php if($p['student_name']): ?><a class="text-link" href="<?= e(url('/alunos/'.$p['student_id'])) ?>"><?= e($p['student_name']) ?></a><?php else: ?>Registro antigo sem aluno<?php endif; ?></td><td><?= $p['work_number']?'nº '.e($p['work_number']):'—' ?></td><td><?= e($p['workshop_name']) ?></td><td><?= e($p['quantity']) ?></td><td><?= !empty($p['delivery_id']) ? 'Entregue' : ($p['availability_status']==='disponivel' ? 'Disponível' : 'Indisponível') ?></td></tr><?php endforeach; ?><?php if(!$productions): ?><tr><td colspan="6">Nenhuma produção relacionada.</td></tr><?php endif; ?></tbody></table></div></div></section>
